 "input_schema": {"type": "object", "properties": {"id": {"type": "string"}}, "required": ["id"]}}

// 2) Claude responde (stop_reason: "tool_use")
{"role": "assistant", "content": [
  {"type": "tool_use", "id": "toolu_01", "name": "buscar_pedido", "input": {"id": "A-42"}}]}

// 3) Tu app ejecuta y responde en un mensaje user
{"role": "user", "content": [
  {"type": "tool_result", "tool_use_id": "toolu_01", "content": "Pedido A-42: enviado"}]}

const maxPasos = 8;
for (let paso = 0; paso < maxPasos; paso++) {
  const accion = await decidir(contexto);
  if (accion.tipo === "finalizar") break;
  contexto = await ejecutarYObservar(accion);
}

function validar(entrada) {
  if (typeof entrada.id !== "string" || !/^[A-Z0-9-]{1,20}$/.test(entrada.id)) {
    throw new Error("Identificador no válido");
  }
  return entrada.id;
}
